function core(label, causes = []) {
  return Object.freeze({
    kind: "metroplat.journal.observation",
    seat: `seat:${label}`,
    claim: tm.mark(`claim:${label}`),
    address: tm.mark(`address:${label}`),
    time: `2026-01-01T00:00:0${label.length}.000Z`,
    causes: Object.freeze(causes),
  });
}

test("journal event uses canonical bytes and the sole ArtifactRef form", () => {
  const event = journalWitness(core("a"));
  assert.equal(event.kind, "metroplat.journal.witness");
  assert.equal(event.bytes, canonicalJson(event.core));
  assert.match(event.id, /^ni:\/\/\/sha-256;[A-Za-z0-9_-]{43}$/u);
  assert.deepEqual(parseJournalWitness(JSON.parse(JSON.stringify(event))), event);
});

test("Operation uses the canonical source API while retaining its persisted action discriminant", () => {
  const declared = operation({ verb: "compatibility-vector", inputFormat: "json", outputFormat: "json", run: (input) => input });
  assert.equal(declared.kind, "metroplat.action");
  assert.equal(declared.verb, "compatibility-vector");
});

test("Inducing is the complete four-morphism process and Settling remains its terminal morphism", () => {
  const admitted = utterance(mark("subject"), mark("predicate"));
  const composed = inducing(admitted);
  const predication = predicate(articulate(admitted));
  const explicit = settleKnowledge(posit(predication, valuationOfCharge(predication, four.witnessedPotential(mark(admitted)))));
  assert.deepEqual(composed, explicit);
  assert.equal(composed.kind, "predication.settlement.filtration");

  const verbs = inducingOperations.map((declared) => declared.verb);
  assert.equal(verbs.filter((verb) => verb === "induce").length, 1);
  assert.equal(verbs.includes("induce-relation"), false);
  assert.equal(verbs.includes("induce-utterance-relation"), false);
});


test("causal graph preserves ancestry, frontier, external causes, and deterministic order", () => {
  const root = journalWitness(core("root"));
  const left = journalWitness(core("left", [root.id]));
  const external = artifactId({ external: true });
  const right = journalWitness(core("right", [root.id, external]));
  const join = journalWitness(core("join", [left.id, right.id]));
  const graph = causalGraphOf([join, right, root, left]);

  assert.deepEqual(graph.roots, [root.id]);
  assert.deepEqual(graph.heads, [join.id]);
  assert.deepEqual([...graph.externalCauses], [external]);
  assert.deepEqual(new Set(ancestorsOf(graph, join.id)), new Set([root.id, left.id, right.id]));
  assert.deepEqual(new Set(descendantsOf(graph, root.id)), new Set([left.id, right.id, join.id]));
  const ordered = topologicalOrder(graph).map((event) => event.id);
  assert.ok(ordered.indexOf(root.id) < ordered.indexOf(left.id));
  assert.ok(ordered.indexOf(root.id) < ordered.indexOf(right.id));
  assert.ok(ordered.indexOf(left.id) < ordered.indexOf(join.id));
  assert.ok(ordered.indexOf(right.id) < ordered.indexOf(join.id));
});

test("causal graph rejects an edited cyclic slice", () => {
  const a = { ...journalWitness(core("a")), id: "a", core: { ...core("a"), causes: ["b"] } };
  const b = { ...journalWitness(core("b")), id: "b", core: { ...core("b"), causes: ["a"] } };
  assert.throws(() => topologicalOrder(causalGraphOf([a, b])), /contains a cycle/u);
});

test("FOUR settling is a lawful closure and reaches a least fixed point for every charge", () => {
  for (const target of chargeValues) {
    const closure = chargeJoinVClosure(target);
    assert.equal(closureOver(chargeValueCategory, closure, chargeSample).kind, "settling.vClosure.law:witness");
    assert.equal(settleFixedPoint(chargeValueCategory, closure, chargeValue("absurd")).kind, "settling.valueCategory.settleFixedPoint:witness");
    assert.equal(settleLeast(chargeValueCategory, closure, chargeValue("absurd"), target).kind, "settling.valueCategory.settleLeast:witness");
    const recovery = spineRecovery(target);
    assert.equal(recovery.kind, "settling.spineRecovery:witness");
    assert.equal(recovery.reachesTarget, true);
  }
});

test("capability delegation attenuates resources and permissions", () => {
  const parent = objectCapability({ holder: "alice", resource: "urn:workspace", actions: ["read", "write"], caveats: ["audited"] });
  const child = capabilityDelegation({
    issuer: "alice",
    audience: "bob",
    parent,
    resource: "urn:workspace/project",
    actions: ["read"],
    caveats: ["bounded"],
  });
  assert.equal(verifyCapabilityDelegation(child).ok, true);
  assert.equal(canInvoke(child.child, { kind: "capability.invocation", actor: "bob", resource: "urn:workspace/project/file", action: "read", input: null }).ok, true);
  assert.equal(canInvoke(child.child, { kind: "capability.invocation", actor: "bob", resource: "urn:workspace/project/file", action: "write", input: null }).ok, false);
});

test("callable standing retains stable capability evidence as an obstruction", () => {
  const claim = capabilityClaim(
    tm.mark("operation:inspect"),
    { kind: "metroplat.capability.effector", declaration: "inspect" },
    null,
  );
  const reading = readCapabilityWitnesses([
    capabilityWitness(claim, "potential", "positive"),
    capabilityWitness(claim, "active", "negative"),
  ]);
  assert.equal(reading.designated.length, 1);
  assert.equal(reading.designated[0].charge, "stable");
  assert.equal(reading.obstructions.length, 1);
  assert.equal(reading.obstructions[0].charge, "stable");
});

test("shared FOUR operations preserve Metro wire coordinates on all finite inputs", () => {
  const bits = [[0, 0], [1, 0], [0, 1], [1, 1]];
  const coordinates = (v) => v.coordinates.map((side) => Number(side.name === "present"));
  for (const [i, left] of chargeValues.entries()) {
    const [a, b] = bits[i];
    assert.deepEqual(coordinates(left), bits[i]);
    assert.deepEqual(coordinates(four.negateValue(left)), [b, a]);
    assert.deepEqual(coordinates(four.conflateValue(left)), [1 - b, 1 - a]);
    for (const [j, right] of chargeValues.entries()) {
      const [c, d] = bits[j];
      for (const [fn, expected] of [
        [four.joinKnowledgeValue, [a | c, b | d]],
        [four.meetKnowledgeValue, [a & c, b & d]],
        [four.joinTruthValue, [a | c, b & d]],
        [four.meetTruthValue, [a & c, b | d]],
        [fiberAlgebra.truthImplicationValue, [Number(!a || c), Number(!b && d)]],
      ]) assert.deepEqual(coordinates(fn(left, right)), expected);
      assert.equal(four.chargeValueIdentity(left, right).left, left);
    }
  }
  for (const name of ["__proto__", "constructor", "toString"]) assert.equal(four.isChargeValueName(name), false);
  assert.deepEqual(four.kleinFourGaugeReceipt().negationOrbit, ["potential", "active"]);
  assert.deepEqual(four.kleinFourGaugeReceipt().conflationOrbit, ["absurd", "stable"]);
});

test("valuation adapters preserve point keys and use the canonical corner operators", () => {
  const points = ["active", "potential", "carrier", "__proto__"];
  const values = Object.fromEntries(points.map((point, i) => [point, chargeValues[i].name]));
  const v = fiberAlgebra.valuationFiberCarrier(points, { ...values, extra: "potential" });
  assert.deepEqual(v.values, values);
  assert.deepEqual(v.points, points);
  for (const [corner, operator] of [
    ["absurd", (x) => x], ["potential", fiberAlgebra.sigmaNucleus],
    ["active", fiberAlgebra.deltaNucleus], ["stable", fiberAlgebra.piNucleus],
  ]) assert.deepEqual(fiberAlgebra.valuationFiberCornerOp(corner, v), operator(v));
  const receipt = fiberAlgebra.valuationQuartetDischargeReceipt(v);
  assert.deepEqual(receipt.valuation, v);
  assert.equal(receipt.stableIsIntersection, true);
  assert.equal(Object.hasOwn(receipt, "absurdIsIntersection"), false);
  assert.throws(() => fiberAlgebra.readValuationFiber(v, "constructor"), TypeError);
  assert.throws(() => fiberAlgebra.valuationFiberCarrier(["missing"], {}), TypeError);
  assert.throws(() => fiberAlgebra.valuationFiberCarrier(["active", "active"], values), TypeError);
});

test("canonical closure adapters retain finite results, opaque point names, and Metro errors", async () => {
  const closure = await import("@lenticule-science/metrologic/articulation/predicating/positing/closure-operator-fiber");
  for (const [boundIndex, bound] of four.chargeValueNames.entries()) {
    const operator = closure.knowledgeJoinClosure(bound);
    assert.equal(operator.name, `joinClosure:${bound}`);
    for (const [seedIndex, seed] of four.chargeValueNames.entries()) {
      const expected = four.chargeValueNames[boundIndex | seedIndex];
      const value = fiberAlgebra.valuationFiberCarrier(["potential"], { potential: seed });
      assert.equal(closure.liftClosure(operator, value).values.potential, expected);
      assert.equal(closure.closureMonadReceipt(operator, "absurd", seed).settled, expected);
      assert.equal(closure.pointwiseClosureFamilyReceipt(operator, value).closed.values.potential, expected);
    }
  }
  const map = closure.reindexMapCarrier(["active"], ["potential"], { active: "potential" });
  assert.deepEqual(map.map, { active: "potential" });
  assert.deepEqual(closure.reindexValuationFiber(map, fiberAlgebra.valuationFiberCarrier(["potential"], { potential: "potential" })).values, { active: "potential" });
  assert.throws(() => closure.chargeClosureCarrier("invalid", {}), { name: "TypeError", message: "chargeClosure: operation for absurd is not a FOUR charge value" });
  assert.throws(() => closure.reindexMapCarrier(["x"], [], {}), { name: "TypeError", message: "reindexMapCarrier: missing target for x" });
  assert.throws(() => closure.pointwiseClosureFamilyReceipt(closure.knowledgeJoinClosure("potential"), fiberAlgebra.valuationFiberCarrier(["a", "b", "c", "d", "e"], Object.fromEntries(["a", "b", "c", "d", "e"].map(key => [key, "absurd"])))), RangeError);
});

